-- 0740: check-in and check-out change meaning in every word people see (release 33 part H, docs/changes/2026-11-07-r33-finishing.md, item 1).
-- The owner's terms: check-in is the pickup, the start of the booking; check-out is the return, the drop-off at the end. The site used the
-- opposite. Wording only: no code, enum, column, key, URL or stored record changes ('pickup' and 'return', return_check_in, the handover routes
-- stay). The renter's own "Check in yourself" (at pickup) and "I've returned the car" were already right and stay as they are.
-- What this migration changes: the messages and history lines of the database functions that speak of a check-out or check-in (each function is
-- read as it is NOW and its string literals flipped, so a later change to a function by another migration is not undone), the field job label in
-- the instant job notices ("Return Check In" becomes "Check-out (return)"), the status transition notes, the task rule descriptions, the text
-- template label of the mid-trip message ("Mid-trip check-in" becomes "Mid-trip check", so it is not mistaken for the pickup), the academy lesson
-- and the notification catalogue rows of the emails whose words changed (the block at the end, generated by supabase/seed/0740_gen_catalogue.mjs).
-- No applied migration is edited.

-- one flip of every "check-in" / "check out" / "checked in" / "checking out" ... in a text; "checked in person" (a licence checked face to face) is not one
create function pg_temp.flip_check(t text) returns text language sql immutable as $$
  select replace(replace(
    regexp_replace(regexp_replace(t,
      '\m(Check|check)(ed|ing)?([- ])in(s?)\M(?! person)', E'\\1\\2\\3\x01OUT\\4', 'g'),
      '\m(Check|check)(ed|ing)?([- ])out(s?)\M', E'\\1\\2\\3\x01IN\\4', 'g'),
    E'\x01OUT', 'out'), E'\x01IN', 'in')
$$;

do $$
declare
  f record;
  v_def text;
  v_new text;
  v_done int := 0;
begin
  for f in
    select p.oid, n.nspname, p.proname
      from pg_proc p join pg_namespace n on n.oid = p.pronamespace
     where n.nspname = 'app' and p.prokind = 'f'
       and p.proname in ('agreement_override', 'bill_damage', 'booking_before_write', 'booking_close_ended', 'charge_after_rental',
                         'deposit_keep_whole', 'field_checkout_job', 'field_deposit_offline', 'field_identity_in_person', 'field_jobs_leg_done',
                         'field_paper_signed', 'handover_details_complete', 'handover_one_screen', 'handover_record_now',
                         'handover_time_correct', 'job_deposits_due', 'record_late_damage', 'report_damage_to_renter',
                         'return_claim_trip_done', 'task_completion_problem')
  loop
    v_def := pg_get_functiondef(f.oid);
    v_new := pg_temp.flip_check(v_def);
    if v_new <> v_def then
      execute v_new;
      v_done := v_done + 1;
    end if;
  end loop;
  if v_done < 15 then raise exception '0740: expected to reword the messages of at least 15 functions, did %', v_done; end if;
end $$;

-- the field job label in the job notices: "New job: Return Check In" is the return, now the check-out
do $$
declare v_def text; v_new text;
begin
  select pg_get_functiondef(p.oid) into v_def from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'app' and p.proname = 'ntf_payload_base';
  v_new := replace(v_def, 'initcap(replace(fj.kind, ''_'', '' ''))',
                   '(case fj.kind when ''return_check_in'' then ''Check-out (return)'' else initcap(replace(fj.kind, ''_'', '' '')) end)');
  if v_new = v_def then raise exception '0740: the job label in app.ntf_payload_base was not found'; end if;
  execute v_new;
end $$;

-- history and the rules that carry words
update status_transitions set note = 'Check-out' where entity = 'booking' and from_status = 'on_rent' and to_status = 'returned' and note = 'Check-in';
update status_transitions set note = 'Check-out' where entity = 'vehicle' and from_status = 'on_rent' and to_status = 'cleaning' and note = 'Check-in';
update task_rules set description = pg_temp.flip_check(description) where description ~* '\m(check)[- ](in|out)\M';
update sms_templates set label = 'Mid-trip check' where code = 'renter_trip_checkin' and label = 'Mid-trip check-in';
update academy_lessons set scenes = replace(scenes::text, 'Check-out stops on a field a claim needs', 'Check-in stops on a field a claim needs')::jsonb
 where scenes::text like '%Check-out stops on a field a claim needs%';

